package com.pousadamarealta;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.pousadamarealta.api.controller.MessageController;
import com.pousadamarealta.api.controller.ReportController;
import com.pousadamarealta.api.controller.ReservationController;
import com.pousadamarealta.api.controller.RoomController;
import com.pousadamarealta.api.dto.*;
import com.pousadamarealta.domain.MessageChannel;
import com.pousadamarealta.domain.RatePlan;
import com.pousadamarealta.domain.ReservationStatus;
import com.pousadamarealta.domain.RoomType;
import com.pousadamarealta.notification.FinanceNotifier;
import com.pousadamarealta.notification.GuestNotifier;
import com.pousadamarealta.notification.HousekeepingNotifier;
import com.pousadamarealta.notification.NotificationService;
import com.pousadamarealta.notification.ReservationObserver;
import com.pousadamarealta.repository.*;
import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import io.javalin.Javalin;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import javax.sql.DataSource;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@Testcontainers
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class IntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18-alpine");

    private static Javalin app;
    private static HttpClient httpClient;
    private static Gson gson;
    private static final int TEST_PORT = 7777;

    @BeforeAll
    static void setup() {
        DataSource dataSource = createDataSource();

        DatabaseInitializer dbInitializer = new DatabaseInitializer(dataSource);
        dbInitializer.initialize();

        RoomRepository roomRepository = new RoomRepository(dataSource);
        roomRepository.initializeRooms();

        MessageRepository messageRepository = new MessageRepository(dataSource);
        NotificationService notificationService = new NotificationService(messageRepository);

        List<ReservationObserver> observers = List.of(
            new GuestNotifier(notificationService),
            new HousekeepingNotifier(notificationService),
            new FinanceNotifier(notificationService)
        );

        ReservationRepository reservationRepository = new ReservationRepository(dataSource, observers);

        RoomController roomController = new RoomController(roomRepository);
        ReservationController reservationController = new ReservationController(
            roomRepository, reservationRepository, observers
        );
        MessageController messageController = new MessageController(messageRepository);
        ReportController reportController = new ReportController(roomRepository, reservationRepository);

        app = Javalin.create();

        app.get("/rooms", roomController::getRooms);
        app.post("/reservations", reservationController::createReservation);
        app.get("/reservations/{id}", reservationController::getReservation);
        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
        app.post("/reservations/{id}/check-in", reservationController::checkIn);
        app.post("/reservations/{id}/check-out", reservationController::checkOut);
        app.get("/reservations/{id}/document", reservationController::getDocument);
        app.get("/messages", messageController::getMessages);
        app.get("/reports/occupancy", reportController::getOccupancyReport);
        app.get("/reports/revenue", reportController::getRevenueReport);

        app.start(TEST_PORT);

        httpClient = HttpClient.newHttpClient();
        gson = new Gson();
    }

    @AfterAll
    static void teardown() {
        if (app != null) {
            app.stop();
        }
    }

    private static DataSource createDataSource() {
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl(postgres.getJdbcUrl());
        config.setUsername(postgres.getUsername());
        config.setPassword(postgres.getPassword());
        config.setMaximumPoolSize(5);
        return new HikariDataSource(config);
    }

    @Test
    @Order(1)
    void shouldListRooms() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/rooms"))
                .GET()
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);

        List<RoomResponse> rooms = gson.fromJson(response.body(), new TypeToken<List<RoomResponse>>(){}.getType());
        assertThat(rooms).hasSize(5);

        RoomResponse room101 = rooms.stream()
            .filter(r -> r.number().equals("101"))
            .findFirst()
            .orElseThrow();

        assertThat(room101.type()).isEqualTo(RoomType.STANDARD);
        assertThat(room101.capacity()).isEqualTo(2);
        assertThat(room101.nightlyRate()).isEqualTo(249.90);
    }

    @Test
    @Order(2)
    void shouldCreateReservation() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest(
            "101",
            "João Silva",
            "joao@example.com",
            "12345678901",
            "2027-07-10",
            "2027-07-12",
            2,
            "STANDARD"
        );

        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(gson.toJson(request)))
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(201);

        ReservationResponse reservation = gson.fromJson(response.body(), ReservationResponse.class);
        assertThat(reservation.id()).isEqualTo(1);
        assertThat(reservation.roomNumber()).isEqualTo("101");
        assertThat(reservation.nights()).isEqualTo(2);
        assertThat(reservation.subtotal()).isEqualTo(599.76);
        assertThat(reservation.discount()).isEqualTo(0.0);
        assertThat(reservation.total()).isEqualTo(599.76);
        assertThat(reservation.status()).isEqualTo(ReservationStatus.PENDING);
        assertThat(reservation.amountPaid()).isEqualTo(0.0);
    }

    @Test
    @Order(3)
    void shouldConfirmReservation() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations/1/confirmation"))
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);

        ReservationResponse reservation = gson.fromJson(response.body(), ReservationResponse.class);
        assertThat(reservation.status()).isEqualTo(ReservationStatus.CONFIRMED);
        assertThat(reservation.amountPaid()).isEqualTo(599.76);
    }

    @Test
    @Order(4)
    void shouldSendNotificationsOnConfirmation() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/messages"))
                .GET()
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);

        List<MessageResponse> messages = gson.fromJson(response.body(), new TypeToken<List<MessageResponse>>(){}.getType());
        assertThat(messages).hasSize(3);

        MessageResponse guestMessage = messages.stream()
            .filter(m -> m.to().equals("joao@example.com"))
            .findFirst()
            .orElseThrow();

        assertThat(guestMessage.channel()).isEqualTo(MessageChannel.EMAIL);
        assertThat(guestMessage.subject()).isEqualTo("Reserva confirmada - Pousada Maré Alta");
        assertThat(guestMessage.body()).contains("João Silva");
        assertThat(guestMessage.body()).contains("Comprovante de reserva nº 1");

        MessageResponse housekeepingMessage = messages.stream()
            .filter(m -> m.to().equals("governanca@pousadamarealta.com.br"))
            .findFirst()
            .orElseThrow();

        assertThat(housekeepingMessage.subject()).isEqualTo("Reserva confirmada - quarto 101");
        assertThat(housekeepingMessage.body()).contains("10/07/2027");
        assertThat(housekeepingMessage.body()).contains("12/07/2027");

        MessageResponse financeMessage = messages.stream()
            .filter(m -> m.to().equals("financeiro@pousadamarealta.com.br"))
            .findFirst()
            .orElseThrow();

        assertThat(financeMessage.subject()).isEqualTo("Pagamento recebido - reserva 1");
        assertThat(financeMessage.body()).contains("R$ 599,76");
    }

    @Test
    @Order(5)
    void shouldCheckIn() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations/1/check-in"))
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);

        ReservationResponse reservation = gson.fromJson(response.body(), ReservationResponse.class);
        assertThat(reservation.status()).isEqualTo(ReservationStatus.CHECKED_IN);
    }

    @Test
    @Order(6)
    void shouldCheckOut() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations/1/check-out"))
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);

        DocumentResponse document = gson.fromJson(response.body(), DocumentResponse.class);
        assertThat(document.title()).isEqualTo("Comprovante de reserva");
        assertThat(document.reservationId()).isEqualTo(1);
    }

    @Test
    @Order(7)
    void shouldCreateNonRefundableReservation() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest(
            "201",
            "Maria Santos",
            "maria@example.com",
            "98765432100",
            "2027-03-10",
            "2027-03-12",
            2,
            "NON_REFUNDABLE"
        );

        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(gson.toJson(request)))
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(201);

        ReservationResponse reservation = gson.fromJson(response.body(), ReservationResponse.class);
        assertThat(reservation.subtotal()).isEqualTo(779.80);
        assertThat(reservation.discount()).isEqualTo(116.97);
        assertThat(reservation.total()).isEqualTo(662.83);
    }

    @Test
    @Order(8)
    void shouldCancelConfirmedReservation() throws Exception {
        httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations/2/confirmation"))
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations/2/cancellation"))
                .POST(HttpRequest.BodyPublishers.noBody())
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);

        ReservationResponse reservation = gson.fromJson(response.body(), ReservationResponse.class);
        assertThat(reservation.status()).isEqualTo(ReservationStatus.CANCELLED);
        assertThat(reservation.refund()).isEqualTo(0.0);
    }

    @Test
    @Order(9)
    void shouldSendCancellationNotifications() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/messages"))
                .GET()
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        List<MessageResponse> messages = gson.fromJson(response.body(), new TypeToken<List<MessageResponse>>(){}.getType());

        long housekeepingCancellations = messages.stream()
            .filter(m -> m.subject().startsWith("Reserva cancelada"))
            .count();

        assertThat(housekeepingCancellations).isEqualTo(1);
    }

    @Test
    @Order(10)
    void shouldGenerateOccupancyReport() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reports/occupancy?date=2027-07-10"))
                .GET()
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);
        assertThat(response.body()).contains("room,type,reservation,check_in,check_out");
        assertThat(response.body()).contains("101,STANDARD,1,2027-07-10,2027-07-12");
        assertThat(response.body()).contains("total,1/5");
    }

    @Test
    @Order(11)
    void shouldGenerateRevenueReport() throws Exception {
        HttpResponse<String> response = httpClient.send(
            HttpRequest.newBuilder()
                .uri(URI.create("http://localhost:" + TEST_PORT + "/reports/revenue?month=2027-07"))
                .GET()
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        assertThat(response.statusCode()).isEqualTo(200);
        assertThat(response.body()).contains("reservation,room,check_in,check_out,status,amount");
        assertThat(response.body()).contains("1,101,2027-07-10,2027-07-12,CHECKED_OUT,599.76");
        assertThat(response.body()).contains("total,599.76");
