                .uri(URI.create("http://localhost:" + TEST_PORT + "/reservations"))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(gson.toJson(request1)))
                .build(),
            HttpResponse.BodyHandlers.ofString()
        );

        CreateReservationRequest request2 = new CreateReservationRequest(
            "202",
            "Carlos Souza",
            "carlos@example.com",
            "33333333333",
            "2027-09-12",
            "2027-09-17",
            2,
            "STANDARD"
        );

